    expectedStatRegexp = concatWordsForRegexp("CREATE COLUMN TABLE DUMMY", "\\(", "double foo", ",", "PRIMARY KEY \\(tKey\\)", ",", "PRIMARY KEY \\(pKey\\)", "\\)", ";");
    assertTrue(statement.matches(expectedStatRegexp));
}

