public void addToAggregateBinaryData() throws Exception {
    MemoryGroupByMeta memoryGroupByMeta = spy(meta);
    memoryGroupByMeta.setAggregateType(new int[] { MemoryGroupByMeta.TYPE_GROUP_COUNT_DISTINCT });
