@Test
public void testBuildsMongoClientOptions() throws Exception {
    MongoProperties props = new MongoProperties.Builder().set(MongoProp.connectionsPerHost, "127").set(MongoProp.connectTimeout, "333").set(MongoProp.maxWaitTime, "12345").set(MongoProp.cursorFinalizerEnabled, "false").set(MongoProp.socketKeepAlive, "true").set(MongoProp.socketTimeout, "4").set(MongoProp.useSSL, "true").set(MongoProp.readPreference, "primary").set(MongoProp.USE_KERBEROS, "false").set(MongoProp.USE_ALL_REPLICA_SET_MEMBERS, "false").build();
    MongoUtilLogger log = Mockito.mock(MongoUtilLogger.class);
    MongoClientOptions options = props.buildMongoClientOptions(log);
    assertEquals(127, options.getConnectionsPerHost());
    assertEquals(333, options.getConnectTimeout());
    assertEquals(12345, options.getMaxWaitTime());
    assertFalse(options.isCursorFinalizerEnabled());
    assertTrue(options.isSocketKeepAlive());
    assertEquals(4, options.getSocketTimeout());
    assertTrue(options.getSocketFactory() instanceof SSLSocketFactory);
    assertEquals(options.getReadPreference(), ReadPreference.primary());
    assertEquals(props.getReadPreference(), ReadPreference.primary());
    assertFalse(props.useAllReplicaSetMembers());
    assertFalse(props.useKerberos());
    assertEquals("MongoProperties:\n" + "connectionsPerHost=127\n" + "connectTimeout=333\n" + "cursorFinalizerEnabled=false\n" + "HOST=localhost\n" + "maxWaitTime=12345\n" + "PASSWORD=\n" + "readPreference=primary\n" + "socketKeepAlive=true\n" + "socketTimeout=4\n" + "USE_ALL_REPLICA_SET_MEMBERS=false\n" + "USE_KERBEROS=false\n" + "useSSL=true\n", props.toString());
}

